// build.gradle.kts: a custom cacheable task with declared inputs and outputs
abstract class Checksum : DefaultTask() {          // @CacheableTask in a plugin
    @get:InputFile @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val source: RegularFileProperty
    @get:OutputFile
    abstract val target: RegularFileProperty

    @TaskAction
    fun run() {
        val bytes = source.get().asFile.readBytes()
        val sha = java.security.MessageDigest.getInstance("SHA-256").digest(bytes)
        target.get().asFile.writeText(sha.joinToString("") { "%02x".format(it) })
    }
}

tasks.register<Checksum>("checksum") {
    source = layout.projectDirectory.file("README.md")
    target = layout.buildDirectory.file("README.sha256")
    outputs.cacheIf { true }    // script-defined types also need this; plugin classes use @CacheableTask alone
}
// 1st run: > Task :checksum        2nd run: > Task :checksum UP-TO-DATE
// after clean with caching on:    > Task :checksum FROM-CACHE

